-- Projet Aya Septembre - Oracle XE (11g and later)
-- Run once in an empty application schema using SQL Developer (F5 / Run Script)
-- or SQL*Plus: @projet_aya_septembre.sql
-- Connect as the same Oracle user configured in FORMATION_USER for the Qt app.
-- This script creates tables in that user's schema; it does not create a database
-- instance, delete existing tables, or insert personal data.
-- IDs are generated by sequences/triggers because the Qt INSERTs omit IDs.

SET DEFINE OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

CREATE TABLE STAGIAIRES (
    ID_STAGIAIRE      NUMBER(10),
    NOM               VARCHAR2(200 CHAR),
    PRENOM            VARCHAR2(200 CHAR),
    EMAIL             VARCHAR2(254 CHAR),
    TELEPHONE         VARCHAR2(8 CHAR),
    ADRESSE           VARCHAR2(200 CHAR),
    DATE_DE_NAISSANCE  DATE,
    SEXE              VARCHAR2(20 CHAR),
    CIN               VARCHAR2(8 CHAR),
    NIVEAU            VARCHAR2(200 CHAR),
    PRIMARY KEY (ID_STAGIAIRE)
);


CREATE TABLE FORMATEURS (
    ID_FORMATEUR  NUMBER(10),
    NOM           VARCHAR2(200 CHAR),
    PRENOM        VARCHAR2(200 CHAR),
    CIN           VARCHAR2(8 CHAR),
    EMAIL         VARCHAR2(254 CHAR),
    TELEPHONE     VARCHAR2(8 CHAR),
    SPECIALITE    VARCHAR2(200 CHAR),
    DATE_EMBAUCHE DATE,
    STATUT        VARCHAR2(100 CHAR),
    SEXE          VARCHAR2(20 CHAR),
    PRIMARY KEY (ID_FORMATEUR)
);


CREATE TABLE FORMER (
    ID_STAGIAIRE NUMBER(10),
    ID_FORMATEUR NUMBER(10),
    PRIMARY KEY (ID_STAGIAIRE, ID_FORMATEUR),
    FOREIGN KEY (ID_STAGIAIRE)
        REFERENCES STAGIAIRES (ID_STAGIAIRE),
    FOREIGN KEY (ID_FORMATEUR)
        REFERENCES FORMATEURS (ID_FORMATEUR)
);

-- Remove assignments before deleting a person, as expected by the Qt UI.
CREATE INDEX IX_FORMER_FORMATEUR ON FORMER (ID_FORMATEUR);

CREATE SEQUENCE SEQ_STAGIAIRES START WITH 1 INCREMENT BY 1
    MAXVALUE 2147483647 NOCYCLE;
CREATE SEQUENCE SEQ_FORMATEURS START WITH 1 INCREMENT BY 1
    MAXVALUE 2147483647 NOCYCLE;

CREATE OR REPLACE TRIGGER BI_STAGIAIRES_ID
BEFORE INSERT ON STAGIAIRES
FOR EACH ROW
BEGIN
    SELECT SEQ_STAGIAIRES.NEXTVAL INTO :NEW.ID_STAGIAIRE FROM DUAL;
END;
/
SHOW ERRORS TRIGGER BI_STAGIAIRES_ID

CREATE OR REPLACE TRIGGER BI_FORMATEURS_ID
BEFORE INSERT ON FORMATEURS
FOR EACH ROW
BEGIN
    SELECT SEQ_FORMATEURS.NEXTVAL INTO :NEW.ID_FORMATEUR FROM DUAL;
END;
/
SHOW ERRORS TRIGGER BI_FORMATEURS_ID

-- Verify that all three tables and both triggers exist and are valid.
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS
FROM USER_OBJECTS
WHERE OBJECT_NAME IN ('STAGIAIRES', 'FORMATEURS', 'FORMER',
                      'BI_STAGIAIRES_ID', 'BI_FORMATEURS_ID')
ORDER BY OBJECT_TYPE, OBJECT_NAME;

PROMPT Schema projet_aya_septembre created.

